export const limitUnitBoardKanjiByGrade = (value: string, grade?: number, unitId?: string): string => {
  if (!grade || grade < 1 || grade > 9) return value;
  const baseUnitId = unitId?.split(':')[0] ?? '';
  return UNIT_BOARD_GRADE_SAFE_BY_UNIT[baseUnitId]?.[value]
    ?? UNIT_BOARD_GRADE_SAFE_GLOBAL[grade]?.[value]
    ?? value;
};
